import {execSync} from 'child_process';import fs from 'fs';
const u=c=>execSync(`node ../tools/ng-facts.mjs usages ${c} --root . --all`).toString().split('\n').filter(l=>l.startsWith('  ')).map(l=>l.trim().split(':')[0]);
const dn={tent:'Tent',ration:'Ration',helmet:'Helmet'};
const dir={Tent:['TentComponent','TentRowComponent','TentListComponent'],Ration:['RationComponent','SupplyTableComponent'],Helmet:['HelmetComponent']};
const hit={};
for(const k in dir){const s=new Set();for(const c of dir[k])u(c).forEach(f=>s.add(f));hit[k]=s;}
const pages={camps:'camps',camp:'camp-detail','legions':'legions',legion:'legion-detail',supplies:'supplies',map:'map',reports:'reports',daily:'report-daily',losses:'report-losses',settings:'settings',archive:'archive'};
const paths={camps:'camps','camp':'camps/:id',legions:'legions',legion:'legions/:id',supplies:'supplies',map:'map',reports:'reports',daily:'reports/daily',losses:'reports/losses',settings:'settings',archive:'archive'};
const provs=['gallia','britannia','hispania','germania','aegyptus','graecia','dacia','syria'];
const out={tentRoutes:[],rationRoutes:[],helmetRoutes:[],unroutedComponents:[]};
const key={Tent:'tentRoutes',Ration:'rationRoutes',Helmet:'helmetRoutes'};
const cap=s=>s[0].toUpperCase()+s.slice(1);
for(const p of provs)for(const k in pages){
 const routed=k!=='archive'||['germania','syria'].includes(p);
 const base=`src/app/provinces/${p}/${pages[k]}.page.`;
 if(!routed){out.unroutedComponents.push(cap(p)+'ArchivePageComponent');continue;}
 for(const t in dir) if(hit[t].has(base+'html')||hit[t].has(base+'ts')){
  // reports page itself vs children: ok per file
  out[key[t]].push(`${p}/${paths[k]}`);}
}
out.unroutedComponents.push('OldDashboardPageComponent');
fs.writeFileSync('/tmp/out.json',JSON.stringify(out,null,1));
console.log(JSON.stringify(out));
